<script setup>import {Head,useForm} from '@inertiajs/vue3';import CustomerShell from '../../Components/CustomerShell.vue';const form=useForm({phone:''});</script><template><Head title="Lengkapi nomor telepon"/><CustomerShell compact-footer><main class="lf-auth-wrap"><form class="lf-auth-card" @submit.prevent="form.put('/account/phone')"><p class="lf-eyebrow">Lengkapi akun</p><h1>Nomor telepon</h1><p>Nomor telepon diperlukan sebelum memakai akun LFAMILIA.</p><label class="text-[10px] font-semibold text-white/70">Nomor telepon<input v-model="form.phone" type="tel" autocomplete="tel" required></label><span v-if="form.errors.phone" class="mt-1 block text-[9px] text-red-300">{{form.errors.phone}}</span><button class="lf-primary mt-3 w-full" :disabled="form.processing">Simpan nomor</button></form></main></CustomerShell></template>